package com.shabakaty.cinemana.local;
import org.json.*;import java.util.*;import java.net.*;import java.io.*;
import com.shabakaty.cinemana.local.LocalAccountStore.*;
/** Merge descriptors without downgrading them to blank compatibility database rows. */
public final class Metadata269 {
 static final String[] KEYS={"nb","ar_title","en_title","custom_ar_title","custom_en_title","kind","rootSeries","season","episodeNummer","episode_flag","imgObjUrl","imgThumbObjUrl","imgMediumThumbObjUrl","year","duration","publishDate","rate","stars","filmRating","seriesRating","finished","ar_content","en_content"};
 static boolean present(Object v){return v!=null&&v!=JSONObject.NULL&&!String.valueOf(v).isEmpty()&&!String.valueOf(v).equals("null");}
 static JSONObject merge(JSONObject preferred,JSONObject fallback)throws JSONException {JSONObject result=new JSONObject();for(String key:KEYS){Object value=preferred.opt(key);if(!present(value))value=fallback.opt(key);if(present(value)){if(value instanceof String&&((String)value).length()>4000)value=((String)value).substring(0,4000);result.put(key,value);}}return result;}
 static JSONObject local(String id)throws Exception {JSONObject result=new JSONObject();String cached; synchronized(LocalRuntime.cache){cached=LocalRuntime.cache.get(id);}if(cached!=null)result=merge(result,new JSONObject(cached));for(ListKind kind:ListKind.values())if(kind!=ListKind.STATE){Item item=LocalRuntime.data().find(kind,id);if(item!=null&&!item.payload.isEmpty())result=merge(result,new JSONObject(item.payload));}return result;}
 static String title(JSONObject o,String fallback){String title=o.optString("ar_title");if(title.isEmpty())title=o.optString("en_title");return title.isEmpty()?fallback:title;}
 static boolean missing(JSONObject o){return title(o,"").isEmpty()||o.optString("imgObjUrl").isEmpty()||o.optString("stars").isEmpty()||o.optString("year").isEmpty();}
 static JSONObject enrich(Item item)throws Exception {JSONObject o=local(item.id);if(!item.payload.isEmpty())o=merge(o,new JSONObject(item.payload));o.put("nb",item.id);if(title(o,"").isEmpty())o.put("en_title",item.title.isEmpty()?"عمل "+item.id:item.title);if(!o.has("kind"))o.put("kind","1");return o;}
 static void persist(String id,JSONObject fresh)throws Exception {JSONObject merged=merge(fresh,local(id));merged.put("nb",id);String payload=merged.toString();if(payload.length()>20000)throw new IOException("metadata limit");LocalRuntime.data().refreshMetadata(new Item(id,title(merged,"عمل "+id),0,payload));synchronized(LocalRuntime.cache){LocalRuntime.cache.put(id,payload);while(LocalRuntime.cache.size()>64)LocalRuntime.cache.remove(LocalRuntime.cache.keySet().iterator().next());}}
 static final Map<String,Long> attempted=new LinkedHashMap<>();
 static void hydrate(List<Item> items){if(LocalRuntime.app==null)return;long stop=System.currentTimeMillis()+12000;int count=0;for(Item item:items){if(count>=5||System.currentTimeMillis()>stop)break;try{JSONObject old=enrich(item);if(!missing(old)){persist(item.id,old);continue;}Long last=attempted.get(item.id);if(last!=null&&System.currentTimeMillis()-last<300000)continue;attempted.put(item.id,System.currentTimeMillis());while(attempted.size()>128)attempted.remove(attempted.keySet().iterator().next());count++;LocalRuntime.log("metadata_repair_begin id="+LocalRuntime.safeId(item.id));JSONObject fresh=new JSONObject(get("allVideoInfo/id/"+item.id,1024*1024));if(!item.id.equals(fresh.optString("nb")))throw new IOException("metadata identity");persist(item.id,fresh);LocalRuntime.log("metadata_repaired id="+LocalRuntime.safeId(item.id));}catch(Exception e){LocalRuntime.failure("metadata_repair",e);}}}
 static String get(String route,int limit)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL("https://cinemana.shabakaty.cc/api/android/"+route).openConnection();try{c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");try{java.lang.reflect.Field field=Class.forName("com.shabakaty.downloader.ns0").getDeclaredField("a");field.setAccessible(true);Object agent=field.get(null);if(agent instanceof String&&!((String)agent).isEmpty())c.setRequestProperty("User-Agent",(String)agent);}catch(Exception ignored){}c.setRequestProperty("Cache-Control","no-cache, no-store");int code=c.getResponseCode();LocalRuntime.log("catalogue_refresh route="+route.split("/")[0]+" status="+code);if(code!=200)throw new IOException("catalogue HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("catalogue limit");out.write(b,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 static boolean category(Object item){try{String name=String.valueOf(item.getClass().getField("enTitle").get(item)).trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");if(Arrays.asList("religious","program","dialogue","biopic series","bollywood","entertaining","reality","war & politics","soap").contains(name))return false;}catch(Exception ignored){}for(String field:new String[]{"imgObjUrl","imgMediumThumbObjUrl","imgThumbObjUrl"})try{Object value=item.getClass().getField(field).get(item);if(value instanceof String){URI uri=new URI((String)value);String path=uri.getPath();if(("https".equals(uri.getScheme())||"http".equals(uri.getScheme()))&&uri.getHost()!=null&&path!=null){String file=path.substring(path.lastIndexOf('/')+1);if(file.length()>5&&!file.toLowerCase(Locale.ROOT).matches("(null|undefined|0|_thumb|_medium_thumb)(\\.[a-z]+)?"))return true;}}}catch(Exception ignored){}return false;}
}
